// Réponses fausses : tirées d'autres histoires, sans les réponses passe-partout
(() => {
  const passePartout = /^(כֵּן|לֹא|תּוֹדָה|בְּסֵדֶר|יוֹפִי|מְצֻיָּן|מְעֻלֶּה|בְּשִׂמְחָה|הִנֵּה)/;
  const reponses = HISTOIRES_VIE.flatMap((h) => h.lignes.filter((l) => l.length > 3 && !passePartout.test(l[3])).map((l) => ({ he: l[3], tr: l[4], fr: l[5], h: h.id })));
  let graine = 7;
  const tirer = (idHistoire) => {
    for (;;) {
      graine = (graine * 31 + 11) % 9973;
      const r = reponses[graine % reponses.length];
      if (r.h !== idHistoire) return r;
    }
  };
  window.STORIES_VIE = HISTOIRES_VIE.map((h) => ({ id: h.id, cat: h.cat, title: h.title, emoji: h.em, who: h.who, mots: h.mots,
    lines: h.lignes.map((l) => {
      const ligne = { he: l[0], tr: l[1], fr: l[2] };
      if (l.length > 3) {
        const a = tirer(h.id); let b = tirer(h.id);
        while (b.he === a.he) b = tirer(h.id);
        ligne.choices = [{ he: l[3], tr: l[4], fr: l[5], ok: true }, { he: a.he, tr: a.tr, fr: a.fr }, { he: b.he, tr: b.tr, fr: b.fr }];
      }
      return ligne;
    }) }));
  HISTOIRES_VIE.forEach((h) => {
    h.mots.forEach((m) => { if (!MOTS_HISTOIRES.some((x) => x[0].normalize('NFC') === m[0].normalize('NFC'))) MOTS_HISTOIRES.push(m); });
    Object.assign(FORMES_HISTOIRES, h.formes);
  });
})();
